From 63b2a52c2c2d453ccf889cc5e74991a2c81aaccd Mon Sep 17 00:00:00 2001
From: ionutrazvanionita <ionutionita@opensips.org>
Date: Wed, 28 Sep 2016 14:34:53 +0300
Subject: [PATCH] [proto_hep] fix bug introduced in 7190a2d

	Commit 7190a2d was freeing the extra chunks twice when
the message was processed as SIP. Now the original hep context
free function is not registered as a context free function, but
called manually each time all the hep processing is done. This
way we avoid the memory leaks that appeared when the message was
not a SIP message, and the chunks were not freed.

diff --git a/modules/proto_hep/hep.c b/modules/proto_hep/hep.c
index 869cd44d3..8756aa9cc 100644
--- a/modules/proto_hep/hep.c
+++ b/modules/proto_hep/hep.c
@@ -778,26 +778,3 @@ safe_exit:

 	return 0;
 }
-
-void free_extra_chunks(struct hep_desc* h)
-{
-	generic_chunk_t *it, *foo=NULL;
-	if (h == NULL)
-		return;
-
-	if (h->version < 3 || h->u.hepv3.chunk_list == NULL)
-		return;
-
-	for (it=h->u.hepv3.chunk_list; it; foo=it, it=it->next) {
-		if (foo) {
-			shm_free(foo->data);
-			shm_free(foo);
-		}
-	}
-
-	if (foo) {
-		shm_free(foo->data);
-		shm_free(foo);
-	}
-
-}

diff --git a/modules/proto_hep/proto_hep.c b/modules/proto_hep/proto_hep.c
index e28b44b38..7fd6161ef 100644
--- a/modules/proto_hep/proto_hep.c
+++ b/modules/proto_hep/proto_hep.c
@@ -192,7 +192,7 @@ static int mod_init(void)
 		}
 	}

-	hep_ctx_idx = context_register_ptr(CONTEXT_GLOBAL, free_hep_context);
+	hep_ctx_idx = context_register_ptr(CONTEXT_GLOBAL, 0);

 	return 0;
 }
@@ -941,7 +941,7 @@ static inline int hep_handle_req(struct tcp_req *req,
 				receive_msg(msg_buf, msg_len, &local_rcv, ctx) <0)
 				LM_ERR("receive_msg failed \n");

-		free_extra_chunks(&hep_ctx->h);
+		free_hep_context(hep_ctx);

 		if (!size && req != &hep_current_req) {
 			/* if we no longer need this tcp_req
@@ -1282,7 +1282,7 @@ static int hep_udp_read_req(struct socket_info *si, int* bytes_read)
 		receive_msg( msg.s, msg.len, &ri, ctx);
 	}

-	free_extra_chunks(&hep_ctx->h);
+	free_hep_context(hep_ctx);

 	return 0;

-- 
2.25.1

